flowchart TB
  subgraph P1["第 1 部 集める"]
    AG@{ svc: "Amazon CloudWatch", label: "CloudWatch agent<br/>カスタムメトリクス" }
  end
  subgraph P2["第 2 部 指標にする"]
    MF@{ svc: "Amazon CloudWatch Logs", label: "metric filter" }
  end
  subgraph P3["第 3 部 流す"]
    SF@{ svc: "Amazon CloudWatch Logs", label: "subscription filter<br/>ログを送る" }
    MS@{ svc: "Amazon CloudWatch", label: "metric streams<br/>メトリクスを送る" }
  end
  subgraph P4["第 4 部 保存と保護"]
    LC@{ svc: "Amazon CloudWatch Logs", label: "log class・retention<br/>S3 Lifecycle" }
    KM@{ svc: "AWS KMS", label: "AWS KMS<br/>ログの暗号化" }
  end
  subgraph P5["第 5 部 探す"]
    LI@{ svc: "Amazon CloudWatch Logs", label: "Logs Insights" }
  end
  P1 ~~~ P2
  P2 ~~~ P3
  P3 ~~~ P4
  P4 ~~~ P5

flowchart TB
  LG@{ svc: "Amazon CloudWatch Logs", label: "log group" }
  SF["subscription filter<br/>gzip で圧縮して送る"]
  KD@{ svc: "Amazon Kinesis Data Streams", label: "Kinesis Data Streams" }
  LA@{ svc: "AWS Lambda", label: "Lambda<br/>base64 で届く" }
  FH@{ svc: "Amazon Data Firehose", label: "Data Firehose" }
  OS["Amazon OpenSearch<br/>Service<br/>Standard の<br/>log group だけ"]
  LG -- "ログ" --> SF
  SF --> KD
  SF --> LA
  SF --> FH
  SF --> OS

flowchart TB
  CW@{ svc: "Amazon CloudWatch", label: "CloudWatch の<br/>メトリクス<br/>全部か filter で一部" }
  MS["metric streams<br/>near-real-time"]
  FH@{ svc: "Amazon Data Firehose", label: "Data Firehose<br/>望む先へ届ける" }
